import { Formik, Form, Field, ErrorMessage } from "formik";
import { object, string } from "yup";
import { Link } from "react-router-dom";
import ROUTES from "../../Routes";
import axios from "axios";
import { nanoid } from "nanoid";
import { useNavigate } from "react-router-dom";

import "./Registration.css";

const Registration = () => {
  const navigate = useNavigate();

  const initialValues = {
    image: "",
    first: "",
    last: "",
    maid: "",
    age: "",
    gender: "",
    email: "",
    phone: "",
    birthdate: "",
    user: "",
    pass: "",
  };

  const validationSchema = object({
    image: string().required("*required"),
    first: string().required("*required"),
    last: string().required("*required"),
    maid: string(),
    age: string().required("*required"),
    gender: string().required("*required"),
    email: string().required("*required"),
    phone: string().required("*required"),
    birthdate: string().required("*required"),
    user: string().required("*required"),
    pass: string().required("*required"),
  });

  const addUser = (e) => {
    // const newUser = {
    //   id: nanoid(3),
    //   firstName: e.first,
    //   lastName: e.last,
    //   maidenName: e.maid,
    //   image: e.image,
    //   age: e.age,
    //   gender: e.gender,
    //   email: e.email,
    //   phone: e.phone,
    //   birthdate: e.birthdate,
    //   username: e.user,
    //   password: e.pass,
    // };
    axios({
      baseURL: "http://localhost:3001/users",
      method: "POST",
      data: {
        id: nanoid(3),
        firstName: e.first,
        lastName: e.last,
        maidenName: e.maid,
        image: e.image,
        age: e.age,
        gender: e.gender,
        email: e.email,
        phone: e.phone,
        birthdate: e.birthdate,
        username: e.user,
        password: e.pass,
      },
    });
